// Material Cost Tracking and Price Intelligence
// Real-time material cost updates and trend analysis

const updateData = $input.first().json;

// Extract update information
const {
  updateType = 'manual', // manual, supplier_api, market_data, user_report
  materials = [],
  supplier = null,
  location = 'general',
  projectId = null,
  timestamp = new Date().toISOString()
} = updateData;

// Material Categories and Specifications
const materialCategories = {
  wire: {
    '12_awg_thhn': { basePrice: 2.50, unit: 'foot', category: 'wire', copperId: 'HG' },
    '14_awg_thhn': { basePrice: 1.80, unit: 'foot', category: 'wire', copperId: 'HG' },
    '10_awg_thhn': { basePrice: 3.20, unit: 'foot', category: 'wire', copperId: 'HG' },
    '8_awg_thhn': { basePrice: 4.80, unit: 'foot', category: 'wire', copperId: 'HG' },
    '6_awg_thhn': { basePrice: 7.20, unit: 'foot', category: 'wire', copperId: 'HG' },
    'romex_12_2': { basePrice: 0.95, unit: 'foot', category: 'wire', copperId: 'HG' },
    'romex_14_2': { basePrice: 0.75, unit: 'foot', category: 'wire', copperId: 'HG' }
  },
  conduit: {
    'emt_1_2': { basePrice: 8.50, unit: '10ft_stick', category: 'conduit' },
    'emt_3_4': { basePrice: 12.00, unit: '10ft_stick', category: 'conduit' },
    'emt_1': { basePrice: 18.50, unit: '10ft_stick', category: 'conduit' },
    'pvc_1_2': { basePrice: 3.20, unit: '10ft_stick', category: 'conduit' },
    'pvc_3_4': { basePrice: 4.80, unit: '10ft_stick', category: 'conduit' },
    'liquid_tight': { basePrice: 2.40, unit: 'foot', category: 'conduit' }
  },
  devices: {
    'outlet_15a_std': { basePrice: 2.50, unit: 'each', category: 'devices' },
    'outlet_20a_std': { basePrice: 4.20, unit: 'each', category: 'devices' },
    'outlet_15a_gfci': { basePrice: 18.50, unit: 'each', category: 'devices' },
    'outlet_20a_gfci': { basePrice: 24.00, unit: 'each', category: 'devices' },
    'switch_single': { basePrice: 1.85, unit: 'each', category: 'devices' },
    'switch_3way': { basePrice: 3.20, unit: 'each', category: 'devices' },
    'switch_dimmer': { basePrice: 28.00, unit: 'each', category: 'devices' },
    'usb_outlet': { basePrice: 35.00, unit: 'each', category: 'devices' }
  },
  panels: {
    'panel_100a_20circuit': { basePrice: 125.00, unit: 'each', category: 'panels' },
    'panel_200a_40circuit': { basePrice: 285.00, unit: 'each', category: 'panels' },
    'subpanel_100a': { basePrice: 95.00, unit: 'each', category: 'panels' },
    'breaker_15a_1pole': { basePrice: 8.50, unit: 'each', category: 'panels' },
    'breaker_20a_1pole': { basePrice: 9.20, unit: 'each', category: 'panels' },
    'breaker_30a_2pole': { basePrice: 28.00, unit: 'each', category: 'panels' },
    'gfci_breaker_15a': { basePrice: 45.00, unit: 'each', category: 'panels' },
    'afci_breaker_15a': { basePrice: 65.00, unit: 'each', category: 'panels' }
  },
  fixtures: {
    'led_recessed_6in': { basePrice: 35.00, unit: 'each', category: 'fixtures' },
    'led_ceiling_flush': { basePrice: 45.00, unit: 'each', category: 'fixtures' },
    'pendant_kitchen': { basePrice: 125.00, unit: 'each', category: 'fixtures' },
    'chandelier_dining': { basePrice: 350.00, unit: 'each', category: 'fixtures' },
    'outdoor_wall_sconce': { basePrice: 85.00, unit: 'each', category: 'fixtures' },
    'can_light_housing': { basePrice: 18.50, unit: 'each', category: 'fixtures' }
  },
  specialty: {
    'smart_switch': { basePrice: 65.00, unit: 'each', category: 'specialty' },
    'motion_sensor': { basePrice: 28.00, unit: 'each', category: 'specialty' },
    'ceiling_fan': { basePrice: 185.00, unit: 'each', category: 'specialty' },
    'exhaust_fan': { basePrice: 95.00, unit: 'each', category: 'specialty' },
    'doorbell_transformer': { basePrice: 25.00, unit: 'each', category: 'specialty' },
    'surge_protector': { basePrice: 145.00, unit: 'each', category: 'specialty' }
  }
};

// Location-based multipliers
const locationMultipliers = {
  urban: 1.25,
  suburban: 1.0,
  rural: 0.85,
  high_cost_area: 1.45,
  general: 1.0
};

// Get current copper price (simplified - would integrate with COMEX API)
function getCopperPriceMultiplier() {
  // Base price assumes $3.50/lb copper
  // This would be updated from real market data
  const currentCopperPrice = 4.25; // Example current price
  const baseCopperPrice = 3.50;
  return currentCopperPrice / baseCopperPrice;
}

// Process material updates
function processMaterialUpdates(materials, location) {
  const copperMultiplier = getCopperPriceMultiplier();
  const locationMultiplier = locationMultipliers[location] || 1.0;
  const processedMaterials = [];

  materials.forEach(material => {
    const {
      materialId,
      supplierPrice = null,
      quantity = 1,
      supplier = 'unknown',
      reportedBy = 'system'
    } = material;

    // Find material in catalog
    let catalogMaterial = null;
    let categoryName = null;

    for (const [category, items] of Object.entries(materialCategories)) {
      if (items[materialId]) {
        catalogMaterial = items[materialId];
        categoryName = category;
        break;
      }
    }

    if (!catalogMaterial) {
      // Handle unknown materials
      processedMaterials.push({
        materialId,
        status: 'unknown_material',
        error: `Material ${materialId} not found in catalog`
      });
      return;
    }

    // Calculate adjusted price
    let adjustedPrice = catalogMaterial.basePrice;

    // Apply copper price multiplier for wire
    if (catalogMaterial.copperId) {
      adjustedPrice *= copperMultiplier;
    }

    // Apply location multiplier
    adjustedPrice *= locationMultiplier;

    // Calculate price variance if supplier price provided
    let priceVariance = null;
    let variancePercentage = null;

    if (supplierPrice !== null) {
      priceVariance = supplierPrice - adjustedPrice;
      variancePercentage = ((supplierPrice - adjustedPrice) / adjustedPrice) * 100;
    }

    processedMaterials.push({
      materialId,
      category: categoryName,
      catalogPrice: Math.round(catalogMaterial.basePrice * 100) / 100,
      adjustedPrice: Math.round(adjustedPrice * 100) / 100,
      supplierPrice,
      priceVariance: priceVariance ? Math.round(priceVariance * 100) / 100 : null,
      variancePercentage: variancePercentage ? Math.round(variancePercentage * 10) / 10 : null,
      unit: catalogMaterial.unit,
      quantity,
      totalCost: Math.round(adjustedPrice * quantity * 100) / 100,
      supplier,
      location,
      reportedBy,
      multipliers: {
        copper: catalogMaterial.copperId ? Math.round(copperMultiplier * 100) / 100 : 1.0,
        location: locationMultiplier
      },
      timestamp: new Date().toISOString()
    });
  });

  return processedMaterials;
}

// Analyze price trends
function analyzePriceTrends(processedMaterials) {
  const trends = {
    categories: {},
    alerts: [],
    overall: {
      avgVariance: 0,
      volatileMaterials: [],
      costIncreases: 0,
      costDecreases: 0
    }
  };

  const variances = processedMaterials
    .filter(m => m.variancePercentage !== null)
    .map(m => m.variancePercentage);

  if (variances.length > 0) {
    trends.overall.avgVariance = Math.round((variances.reduce((sum, v) => sum + v, 0) / variances.length) * 10) / 10;
    trends.overall.costIncreases = variances.filter(v => v > 0).length;
    trends.overall.costDecreases = variances.filter(v => v < 0).length;
  }

  // Analyze by category
  processedMaterials.forEach(material => {
    if (!trends.categories[material.category]) {
      trends.categories[material.category] = {
        materials: [],
        avgVariance: 0,
        priceAlert: false
      };
    }

    trends.categories[material.category].materials.push(material);

    // Check for significant price changes
    if (material.variancePercentage !== null) {
      if (Math.abs(material.variancePercentage) > 15) {
        trends.overall.volatileMaterials.push(material.materialId);
        trends.categories[material.category].priceAlert = true;

        trends.alerts.push({
          type: 'price_variance',
          severity: Math.abs(material.variancePercentage) > 25 ? 'high' : 'medium',
          material: material.materialId,
          variance: material.variancePercentage,
          message: `${material.materialId} price ${material.variancePercentage > 0 ? 'increased' : 'decreased'} by ${Math.abs(material.variancePercentage).toFixed(1)}%`
        });
      }
    }
  });

  // Calculate category averages
  Object.keys(trends.categories).forEach(category => {
    const categoryMaterials = trends.categories[category].materials;
    const categoryVariances = categoryMaterials
      .filter(m => m.variancePercentage !== null)
      .map(m => m.variancePercentage);

    if (categoryVariances.length > 0) {
      trends.categories[category].avgVariance = Math.round(
        (categoryVariances.reduce((sum, v) => sum + v, 0) / categoryVariances.length) * 10
      ) / 10;
    }
  });

  return trends;
}

// Generate cost impact analysis
function generateCostImpact(processedMaterials, projectId) {
  const impact = {
    projectId,
    totalMaterials: processedMaterials.length,
    totalCost: processedMaterials.reduce((sum, m) => sum + m.totalCost, 0),
    costByCategory: {},
    recommendations: [],
    riskLevel: 'low'
  };

  // Calculate cost by category
  processedMaterials.forEach(material => {
    if (!impact.costByCategory[material.category]) {
      impact.costByCategory[material.category] = {
        totalCost: 0,
        materialCount: 0,
        avgPrice: 0
      };
    }

    impact.costByCategory[material.category].totalCost += material.totalCost;
    impact.costByCategory[material.category].materialCount += 1;
  });

  // Calculate averages and risk level
  let totalVariance = 0;
  let varianceCount = 0;

  Object.keys(impact.costByCategory).forEach(category => {
    const categoryData = impact.costByCategory[category];
    categoryData.avgPrice = Math.round((categoryData.totalCost / categoryData.materialCount) * 100) / 100;

    const categoryMaterials = processedMaterials.filter(m => m.category === category);
    const categoryVariances = categoryMaterials.filter(m => m.variancePercentage !== null);

    if (categoryVariances.length > 0) {
      const avgVariance = categoryVariances.reduce((sum, m) => sum + Math.abs(m.variancePercentage), 0) / categoryVariances.length;
      totalVariance += avgVariance;
      varianceCount += 1;
    }
  });

  // Determine risk level
  if (varianceCount > 0) {
    const overallVariance = totalVariance / varianceCount;
    if (overallVariance > 20) {
      impact.riskLevel = 'high';
    } else if (overallVariance > 10) {
      impact.riskLevel = 'medium';
    }
  }

  // Generate recommendations
  if (impact.riskLevel === 'high') {
    impact.recommendations.push('Consider locking in material prices with suppliers');
    impact.recommendations.push('Review alternative materials with stable pricing');
    impact.recommendations.push('Increase project contingency by 10-15%');
  } else if (impact.riskLevel === 'medium') {
    impact.recommendations.push('Monitor material prices closely');
    impact.recommendations.push('Consider bulk purchasing for volatile materials');
  }

  return impact;
}

// Process the material cost update
const processedMaterials = processMaterialUpdates(materials, location);
const priceTrends = analyzePriceTrends(processedMaterials);
const costImpact = generateCostImpact(processedMaterials, projectId);

// Create comprehensive material cost report
const report = {
  updateId: `MCU-${Date.now()}`,
  timestamp,
  updateType,
  projectId,
  location,
  supplier,
  materials: processedMaterials,
  trends: priceTrends,
  impact: costImpact,
  marketConditions: {
    copperPrice: getCopperPriceMultiplier(),
    locationMultiplier: locationMultipliers[location] || 1.0,
    marketTrend: priceTrends.overall.avgVariance > 5 ? 'increasing' : priceTrends.overall.avgVariance < -5 ? 'decreasing' : 'stable'
  },
  summary: {
    materialsProcessed: processedMaterials.length,
    totalEstimatedCost: Math.round(costImpact.totalCost * 100) / 100,
    priceAlertsCount: priceTrends.alerts.length,
    riskLevel: costImpact.riskLevel,
    recommendationsCount: costImpact.recommendations.length
  },
  metadata: {
    generatedBy: 'ElectricalAI Pro Material Cost Tracker',
    version: '1.2.0',
    processingLocation: location,
    dataSource: updateType
  }
};

return [{ json: report }];

// Update material costs with real-time copper pricing
const costReport = $('Process Material Costs').first().json;
const copperData = $('Get Copper Prices').first();

// Update copper pricing if API call was successful
if (copperData && copperData.json && copperData.json.rates && copperData.json.rates.COPPER) {
  const currentCopperPrice = copperData.json.rates.COPPER;
  const baseCopperPrice = 3.50; // Base price in our system
  const realCopperMultiplier = currentCopperPrice / baseCopperPrice;

  // Update all copper-containing materials
  costReport.materials.forEach(material => {
    if (material.multipliers && material.multipliers.copper > 1.0) {
      // Recalculate with real copper price
      const basePrice = material.catalogPrice;
      const locationMultiplier = material.multipliers.location;

      material.adjustedPrice = Math.round(basePrice * realCopperMultiplier * locationMultiplier * 100) / 100;
      material.totalCost = Math.round(material.adjustedPrice * material.quantity * 100) / 100;
      material.multipliers.copper = Math.round(realCopperMultiplier * 100) / 100;

      // Recalculate variance if supplier price exists
      if (material.supplierPrice !== null) {
        material.priceVariance = Math.round((material.supplierPrice - material.adjustedPrice) * 100) / 100;
        material.variancePercentage = Math.round(((material.supplierPrice - material.adjustedPrice) / material.adjustedPrice) * 1000) / 10;
      }
    }
  });

  // Update market conditions
  costReport.marketConditions.copperPrice = realCopperMultiplier;
  costReport.marketConditions.realTimePricing = true;
  costReport.marketConditions.copperPriceUSD = currentCopperPrice;
  costReport.marketConditions.lastUpdated = copperData.json.timestamp;

  // Recalculate total cost
  costReport.impact.totalCost = costReport.materials.reduce((sum, m) => sum + m.totalCost, 0);
  costReport.summary.totalEstimatedCost = Math.round(costReport.impact.totalCost * 100) / 100;
} else {
  costReport.marketConditions.realTimePricing = false;
  costReport.marketConditions.note = 'Using cached copper pricing';
}

return [{ json: costReport }];

// Generate procurement recommendations
const costData = $('Save Cost Update').first().json;

// Analyze materials for procurement optimization
const procurementAnalysis = {
  bulkOpportunities: [],
  alternativeMaterials: [],
  supplierRecommendations: [],
  timingRecommendations: []
};

// Group materials by category for bulk opportunities
const categoryTotals = {};
costData.materials.forEach(material => {
  if (!categoryTotals[material.category]) {
    categoryTotals[material.category] = {
      totalCost: 0,
      totalQuantity: 0,
      materials: []
    };
  }

  categoryTotals[material.category].totalCost += material.totalCost;
  categoryTotals[material.category].totalQuantity += material.quantity;
  categoryTotals[material.category].materials.push(material);
});

// Identify bulk opportunities
Object.entries(categoryTotals).forEach(([category, data]) => {
  if (data.totalCost > 500) { // Minimum bulk threshold
    procurementAnalysis.bulkOpportunities.push({
      category,
      totalCost: data.totalCost,
      materialCount: data.materials.length,
      potentialSavings: Math.round(data.totalCost * 0.08), // 8% bulk discount
      recommendation: `Consider bulk purchasing ${category} materials for 8% savings`
    });
  }
});

// Identify volatile materials for timing recommendations
costData.materials.forEach(material => {
  if (material.variancePercentage && Math.abs(material.variancePercentage) > 10) {
    if (material.variancePercentage > 0) {
      procurementAnalysis.timingRecommendations.push({
        material: material.materialId,
        action: 'purchase_soon',
        reason: `Price increasing (${material.variancePercentage}%)`,
        urgency: material.variancePercentage > 20 ? 'high' : 'medium'
      });
    } else {
      procurementAnalysis.timingRecommendations.push({
        material: material.materialId,
        action: 'wait_for_further_decline',
        reason: `Price declining (${material.variancePercentage}%)`,
        urgency: 'low'
      });
    }
  }
});

// Generate supplier recommendations based on variance
const supplierPerformance = {};
costData.materials.forEach(material => {
  if (material.supplier && material.supplier !== 'unknown' && material.variancePercentage !== null) {
    if (!supplierPerformance[material.supplier]) {
      supplierPerformance[material.supplier] = {
        materials: [],
        avgVariance: 0,
        totalSavings: 0
      };
    }

    supplierPerformance[material.supplier].materials.push(material);
    supplierPerformance[material.supplier].totalSavings += (material.priceVariance || 0) * material.quantity;
  }
});

// Calculate supplier performance metrics
Object.entries(supplierPerformance).forEach(([supplier, data]) => {
  const variances = data.materials.map(m => m.variancePercentage);
  data.avgVariance = variances.reduce((sum, v) => sum + v, 0) / variances.length;

  procurementAnalysis.supplierRecommendations.push({
    supplier,
    materialCount: data.materials.length,
    avgVariance: Math.round(data.avgVariance * 10) / 10,
    totalSavings: Math.round(data.totalSavings * 100) / 100,
    rating: data.avgVariance < -5 ? 'excellent' : data.avgVariance < 0 ? 'good' : data.avgVariance < 10 ? 'fair' : 'poor'
  });
});

// Create comprehensive procurement report
const procurementReport = {
  ...costData,
  procurement: procurementAnalysis,
  summary: {
    ...costData.summary,
    bulkSavingsOpportunity: procurementAnalysis.bulkOpportunities.reduce((sum, opp) => sum + opp.potentialSavings, 0),
    urgentPurchases: procurementAnalysis.timingRecommendations.filter(r => r.urgency === 'high').length,
    topSupplier: procurementAnalysis.supplierRecommendations.length > 0 ? 
      procurementAnalysis.supplierRecommendations.sort((a, b) => a.avgVariance - b.avgVariance)[0].supplier : null
  }
};

return [{ json: procurementReport }];

// Format final response for API consumers
const fullReport = $('Generate Procurement Report').first().json;

const response = {
  success: true,
  updateId: fullReport.updateId,
  projectId: fullReport.projectId,
  costs: {
    totalEstimated: fullReport.summary.totalEstimatedCost,
    materialsProcessed: fullReport.summary.materialsProcessed,
    riskLevel: fullReport.impact.riskLevel,
    byCategory: fullReport.impact.costByCategory
  },
  pricing: {
    copperMultiplier: fullReport.marketConditions.copperPrice,
    locationMultiplier: fullReport.marketConditions.locationMultiplier,
    marketTrend: fullReport.marketConditions.marketTrend,
    realTimePricing: fullReport.marketConditions.realTimePricing || false
  },
  alerts: fullReport.trends.alerts.map(alert => ({
    type: alert.type,
    severity: alert.severity,
    material: alert.material,
    message: alert.message
  })),
  procurement: {
    bulkSavings: fullReport.summary.bulkSavingsOpportunity || 0,
    urgentPurchases: fullReport.summary.urgentPurchases || 0,
    topSupplier: fullReport.summary.topSupplier,
    opportunities: fullReport.procurement.bulkOpportunities.slice(0, 3), // Top 3
    timing: fullReport.procurement.timingRecommendations.filter(r => r.urgency === 'high')
  },
  recommendations: fullReport.impact.recommendations,
  timestamp: fullReport.timestamp,
  location: fullReport.location
};

return [{ json: response }];
